using Microsoft.CodeAnalysis;
using Microsoft.CodeAnalysis.CSharp;

public class A5ClosedGenericStructFromReferencedAssemblyTests
{
    private readonly ITestOutputHelper testOutputHelper;

    public A5ClosedGenericStructFromReferencedAssemblyTests(ITestOutputHelper testOutputHelper)
    {
        this.testOutputHelper = testOutputHelper;
    }

    [Fact]
    public void A5_F1_GenericStructFromReferencedAssembly_DoesNotThrow()
    {
        string librarySource = """
namespace RefLib
{
    public struct GenericStruct<T>
    {
        public T Value;
    }
}
""";

        string consumerSource = """
using System;
using MessagePack;
using RefLib;

namespace TempProject
{
    [MessagePackObject]
    public class MyObject
    {
        [Key(0)]
        public GenericStruct<int> Value { get; set; }

        [Key(1)]
        public GenericStruct<string> Value2 { get; set; }
    }
}
""";

        this.RunAndAssertNoGeneratorFailure(librarySource, consumerSource);
    }

    [Fact]
    public void A5_F1_GenericRecordStructFromReferencedAssembly_DoesNotThrow()
    {
        string librarySource = """
namespace RefLib
{
    public record struct GenericRecordStruct<T>
    {
        public T Value { get; set; }
    }
}
""";

        string consumerSource = """
using System;
using MessagePack;
using RefLib;

namespace TempProject
{
    [MessagePackObject]
    public class MyObject
    {
        [Key(0)]
        public GenericRecordStruct<int> Value { get; set; }

        [Key(1)]
        public GenericRecordStruct<string> Value2 { get; set; }
    }
}
""";

        this.RunAndAssertNoGeneratorFailure(librarySource, consumerSource);
    }

    [Fact]
    public void A5_F1_MessagePackObjectGenericStructsFromReferencedAssembly_DoesNotThrow()
    {
        string librarySource = """
using MessagePack;

namespace RefLib
{
    [MessagePackObject]
    public struct GenericStruct<T>
    {
        [Key(0)]
        public T Value { get; set; }
    }

    [MessagePackObject]
    public record struct GenericRecordStruct<T>
    {
        [Key(0)]
        public T Value { get; set; }
    }
}
""";

        string consumerSource = """
using System;
using MessagePack;
using RefLib;

namespace TempProject
{
    [MessagePackObject]
    public class MyObject
    {
        [Key(0)]
        public GenericStruct<int> Value { get; set; }

        [Key(1)]
        public GenericRecordStruct<int> Value2 { get; set; }
    }
}
""";

        this.RunAndAssertNoGeneratorFailure(librarySource, consumerSource);
    }

    private static System.Collections.Generic.List<MetadataReference> GetPlatformReferences()
    {
        var seen = new System.Collections.Generic.HashSet<string>(System.StringComparer.OrdinalIgnoreCase);
        var references = new System.Collections.Generic.List<MetadataReference>();

        // Make sure the generator assembly (and its dependencies) are loaded.
        _ = typeof(MessagePack.SourceGenerator.MessagePackGenerator).Assembly;

        if (System.AppContext.GetData("TRUSTED_PLATFORM_ASSEMBLIES") is string tpa)
        {
            foreach (string path in tpa.Split(System.IO.Path.PathSeparator))
            {
                if (string.IsNullOrEmpty(path) || !System.IO.File.Exists(path))
                {
                    continue;
                }

                string name = System.IO.Path.GetFileNameWithoutExtension(path);
                if (seen.Add(name))
                {
                    references.Add(MetadataReference.CreateFromFile(path));
                }
            }
        }

        foreach (System.Reflection.Assembly assembly in System.AppDomain.CurrentDomain.GetAssemblies())
        {
            if (assembly.IsDynamic)
            {
                continue;
            }

            string location;
            try
            {
                location = assembly.Location;
            }
            catch (System.NotSupportedException)
            {
                continue;
            }

            if (string.IsNullOrEmpty(location) || !System.IO.File.Exists(location))
            {
                continue;
            }

            string name = System.IO.Path.GetFileNameWithoutExtension(location);
            if (seen.Add(name))
            {
                references.Add(MetadataReference.CreateFromFile(location));
            }
        }

        return references;
    }

    private void RunAndAssertNoGeneratorFailure(string librarySource, string consumerSource)
    {
        var parseOptions = new CSharpParseOptions(LanguageVersion.Latest);
        var compilationOptions = new CSharpCompilationOptions(OutputKind.DynamicallyLinkedLibrary);
        var platformReferences = GetPlatformReferences();

        CSharpCompilation libraryCompilation = CSharpCompilation.Create(
            "RefLib",
            new[] { CSharpSyntaxTree.ParseText(librarySource, parseOptions) },
            platformReferences,
            compilationOptions);

        byte[] image;
        using (var stream = new System.IO.MemoryStream())
        {
            var emitResult = libraryCompilation.Emit(stream);
            foreach (var diagnostic in emitResult.Diagnostics)
            {
                this.testOutputHelper.WriteLine("Library: " + diagnostic.ToString());
            }

            Assert.True(emitResult.Success, "The referenced library failed to compile.");
            image = stream.ToArray();
        }

        var consumerReferences = new System.Collections.Generic.List<MetadataReference>(platformReferences);
        consumerReferences.Add(MetadataReference.CreateFromImage(image));

        CSharpCompilation consumerCompilation = CSharpCompilation.Create(
            "TempProject",
            new[] { CSharpSyntaxTree.ParseText(consumerSource, parseOptions) },
            consumerReferences,
            compilationOptions);

        foreach (var diagnostic in consumerCompilation.GetDiagnostics())
        {
            if (diagnostic.Severity == DiagnosticSeverity.Error)
            {
                this.testOutputHelper.WriteLine("Consumer: " + diagnostic.ToString());
            }

            Assert.NotEqual(DiagnosticSeverity.Error, diagnostic.Severity);
        }

        GeneratorDriver driver = CSharpGeneratorDriver.Create(new MessagePack.SourceGenerator.MessagePackGenerator());
        driver = driver.RunGeneratorsAndUpdateCompilation(consumerCompilation, out Compilation outputCompilation, out var generatorDiagnostics);

        GeneratorDriverRunResult runResult = driver.GetRunResult();
        foreach (GeneratorRunResult result in runResult.Results)
        {
            if (result.Exception is not null)
            {
                this.testOutputHelper.WriteLine("Generator exception: " + result.Exception.ToString());
            }

            Assert.Null(result.Exception);
        }

        foreach (var diagnostic in generatorDiagnostics)
        {
            this.testOutputHelper.WriteLine("Generator: " + diagnostic.ToString());
            Assert.NotEqual("CS8785", diagnostic.Id);
        }

        foreach (var diagnostic in runResult.Diagnostics)
        {
            Assert.NotEqual("CS8785", diagnostic.Id);
        }
    }
}
